/**
 * Local-First Bundle Rendering
 * Stages all deployment artifacts (Compose files, .env, scripts) into a private
 * temp directory before the deploy touches anything outside this machine. The
 * .env and app.env in it carry every secret the servers get, so it lives only
 * while the work that uploads it runs: the deploy removes it once its
 * dispatch settles (orchestrator), and scale goes through withBundle.
 */

import { cpSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { stripOperatorSecretLines } from '../config-registry.js';
import { formatDotenvLine, parseDotenv } from '../dotenv.js';
import { dockerSocketProxyImageRef, resolveDbImage, traefikImageRef } from '../images.js';
import { perfTimer } from '../perf.js';
import {
  ADDON_JOB_SCRIPT,
  ADDON_SERVICES_SCRIPT,
  ADDON_STATUS_FILE,
  backgroundAddons,
  renderAddonJobScript,
  renderAddonServicesScript,
} from '../services/addon-start.js';
import { composeStandbyScaledServices, enabledAddonNames } from '../services/standby-policy.js';
import { makeTempDir, removeTempDir } from '../temp-dir.js';
import { appStorageCredential, buildAppRuntimeEnv } from './app-runtime-env.js';
import { renderComposeCommand, VC_COMPOSE, VC_COMPOSE_SCRIPT } from './compose/command.js';
import { COMPOSE_WALG_ROLE_HOST_DIR, walgRoleReadFragment } from './walg-role.js';

/**
 * The two compose files EVERY deployed server carries, in `-f` order.
 * `docker-compose.prod.yml` must follow the base file: it overrides it.
 */
const COMPOSE_BASE_FILES = ['docker-compose.yml', 'docker-compose.prod.yml'];

/**
 * The node-side script that prints the compose `--scale <svc>=0` flags holding
 * primary-only add-ons (n8n, metabase) at zero on a compose-ha standby. They
 * write to the primary database, so on a read-only replica they only
 * crash-loop. Written into every bundle beside reconcile.sh; on a node whose
 * role file (`.vibecarbon-role/walg-role`) does not say `standby` it prints
 * nothing.
 *
 * The `-f` set never depends on role: n8n's and metabase's overlays both carry
 * a `db:` key, so a role-dependent file set would render db differently and
 * recreate it. Role is only this runtime fragment, appended to every
 * whole-stack `up` (reconcile.sh, the systemd ExecStart, scale.js's
 * post-restore recreate). `--scale` is not part of the rendered config, so
 * `config` and `pull` do not carry it.
 */
export const STANDBY_SCALE_SCRIPT = 'standby-scale.sh';

/** The shell fragment, run from the project dir; empty when the script is absent. */
export const STANDBY_SCALE_FLAG = `$([ -f ${STANDBY_SCALE_SCRIPT} ] && sh ${STANDBY_SCALE_SCRIPT})`;

/** The same for a systemd unit: `$$` passes a literal `$` through systemd's expansion. */
export const STANDBY_SCALE_FLAG_SYSTEMD = `$${STANDBY_SCALE_FLAG}`;

/**
 * Render standby-scale.sh for the given compose services. It reads the node's
 * wal-g role file (`.vibecarbon-role/walg-role`, through the one parser,
 * walgRoleReadFragment), prints `--scale <svc>=0` for each service on a
 * standby, nothing otherwise, and always exits 0.
 * @param {string[]} services
 */
export function renderStandbyScaleScript(services) {
  const flags = services.map((svc) => `--scale ${svc}=0`).join(' ');
  const print = flags ? `if [ "$VC_WALG_ROLE" = standby ]; then echo '${flags}'; fi\n` : '';
  return `#!/bin/sh
# Generated by Vibecarbon. Prints the compose --scale flags that hold
# primary-only add-ons at zero on a compose-ha standby (its wal-g role file
# says standby).
${walgRoleReadFragment(`${COMPOSE_WALG_ROLE_HOST_DIR}/walg-role`)}
${print}exit 0
`;
}

/**
 * Every OPTIONAL compose file a deployed server can carry, in `-f` order, each
 * with the bundle option that selects it. `renderBundle` copies a file to the
 * server only when its option is on (see rootFiles below), so the two stay in
 * step by construction rather than by convention.
 *
 * This is the only compose file list in the tree: `composeFileFlags` renders
 * it into vc-compose (compose/command.js), and every Compose call on a server
 * runs that script.
 */
const COMPOSE_OPTIONAL_FILES = [
  { file: 'docker-compose.observability.yml', when: (o) => o.observability },
  { file: 'docker-compose.observability.prod.yml', when: (o) => o.observability },
  { file: 'docker-compose.n8n.yml', when: (o) => o.n8n },
  { file: 'docker-compose.n8n.prod.yml', when: (o) => o.n8n },
  { file: 'docker-compose.metabase.yml', when: (o) => o.metabase },
  { file: 'docker-compose.metabase.prod.yml', when: (o) => o.metabase },
  { file: 'docker-compose.redis.yml', when: (o) => o.redis },
  { file: 'docker-compose.redis.prod.yml', when: (o) => o.redis },
];

/**
 * Render the reconcile.sh script. Every Compose call in it runs vc-compose,
 * which carries the deploy's `-f` set and adds the compose-ha replication
 * overlay (5433 publish for streaming replication) when the node has it.
 */
export function renderReconcileScript(projectName, isFast = false) {
  // The core stack only: the add-ons ${ADDON_SERVICES_SCRIPT} names are left to
  // the background job (services/addon-start.js), which pulls their images.
  const pullStep = isFast
    ? ''
    : `
# 2. Pull latest images if needed
echo "Pulling images..."
${VC_COMPOSE} pull --quiet --policy missing --ignore-buildable $up_services || true
`;

  return `#!/bin/bash
set -e

# Declarative Compose Reconciler
# Generated by Vibecarbon

PROJECT_DIR="\${VC_PROJECT_DIR:-/opt/${projectName}}"
cd "$PROJECT_DIR"

echo "Reconciling project: ${projectName}..."

echo "File layout in $(pwd):"
ls -R | grep ":$" | sed 's/:$//' | xargs -I {} sh -c "echo '{}:' && ls {} | head -n 5"

if [ -f ".env" ]; then
  echo "Found .env file"
  # Don't print secrets, but check for existence of keys
  grep -E "^(S3_BUCKET|PROJECT_NAME|APP_IMAGE)=" .env | sed 's/=.*$/=***/'
else
  echo "WARNING: .env file NOT FOUND in $(pwd)"
fi


# 0. The previous deploy's add-on job, if one is still going, is stopped
# before ANY container change below (the removed-network sweep included):
# this deploy's compose operations must never overlap its.
if [ -f ${ADDON_JOB_SCRIPT} ]; then sh ${ADDON_JOB_SCRIPT} stop; fi

# 1. Self-heal containers pointing at a removed network
# When a network's definition changes (e.g. an IPAM subnet pin arriving in the
# base file), compose stops every attached container, removes the network and
# creates a replacement — but only recreates containers whose own config-hash
# changed. The rest keep endpoint config referencing the dead network ID and
# can never start again ("network <id> not found"), so every subsequent up
# fails until they're removed. Such containers are unstartable by definition;
# removing them is safe and the up step recreates them on the current network.
echo "Checking for containers attached to removed networks..."
live_network_ids="$(docker network ls -q --no-trunc)"
for container_id in $(docker ps -aq --filter "label=com.docker.compose.project=${projectName}"); do
  for network_id in $(docker inspect --format '{{range .NetworkSettings.Networks}}{{.NetworkID}} {{end}}' "$container_id" 2>/dev/null); do
    if ! printf '%s\\n' "$live_network_ids" | grep -qx "$network_id"; then
      container_name="$(docker inspect --format '{{.Name}}' "$container_id" 2>/dev/null || echo "$container_id")"
      echo "Removing \${container_name#/}, attached to removed network \${network_id:0:12}"
      docker rm -f "$container_id" > /dev/null || true
      break
    fi
  done
done

# Add-ons off the critical path: the services ${ADDON_SERVICES_SCRIPT} prints (none
# on a compose-ha standby, none without background add-ons) are left out of the
# up below and started by ${ADDON_JOB_SCRIPT} in the background afterwards. The
# up then names every OTHER service of the rendered stack: the core.
deferred="$(if [ -f ${ADDON_SERVICES_SCRIPT} ]; then sh ${ADDON_SERVICES_SCRIPT}; fi)"
up_services=""
if [ -n "$deferred" ]; then
  up_services="$(${VC_COMPOSE} config --services | grep -vxF -e "$deferred" | tr '\\n' ' ')"
fi
${pullStep}
# 3. Re-create containers if state differs
#
# RCA instrumentation (2026-08-06 warm recreate-wave, open): preserve the exact
# rendered config every reconcile plans against — first = the cold deploy's
# view, last = the most recent. When a warm up unexpectedly recreates services
# despite byte-identical inputs, \`diff .vc-render-first.yaml
# .vc-render-last.yaml\` on the server names the drifting keys directly.
# Rendered values are no more sensitive than .env in this same root-only dir.
echo "Updating containers..."
${VC_COMPOSE} config > .vc-render-last.yaml 2>/dev/null || true
[ -f .vc-render-first.yaml ] || cp .vc-render-last.yaml .vc-render-first.yaml 2>/dev/null || true
${VC_COMPOSE} up -d --remove-orphans ${STANDBY_SCALE_FLAG} $up_services

# 3b. The add-ons, detached so this ssh session (the deploy) does not wait for
# them; progress and the result go to ${ADDON_STATUS_FILE}.
if [ -n "$up_services" ]; then
  echo "Starting add-ons in the background (progress: ${ADDON_STATUS_FILE})"
  setsid nohup /bin/sh ${ADDON_JOB_SCRIPT} > /dev/null 2>&1 < /dev/null &
else
  # No job on this node (a compose-ha standby, or no background add-on): no
  # status file a reader could take for this deploy's.
  rm -f ${ADDON_STATUS_FILE}
fi

# 4. Ensure systemd service is active (if applicable)
if [ -f "/etc/systemd/system/${projectName}.service" ]; then
  echo "Ensuring systemd service is active..."
  systemctl daemon-reload
  systemctl enable "${projectName}.service"
fi

echo "Reconciliation complete."
`;
}

/**
 * Render the systemd service unit. Its up and down run vc-compose, like
 * reconcile.sh: compose-ha nodes carry docker-compose.replication.yml (5433
 * publish + repl-gateway), and a unit up without it would recreate db minus
 * the replication port and --remove-orphans would delete repl-gateway, so a
 * node reboot would silently break replication transport. The standby-scale
 * fragment needs command substitution, which systemd has not, so the command
 * runs through bash; `$$` passes a literal `$` through systemd's expansion
 * (verified on systemd 255).
 */
export function renderSystemdUnit(projectName) {
  return `[Unit]
Description=Vibecarbon Project: ${projectName}
After=docker.service
Requires=docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
WorkingDirectory=/opt/${projectName}
ExecStart=/bin/bash -c '${VC_COMPOSE} up -d --remove-orphans ${STANDBY_SCALE_FLAG_SYSTEMD}'
ExecStop=/bin/bash -c '${VC_COMPOSE} down'
Restart=on-failure

[Install]
WantedBy=multi-user.target
`;
}

/**
 * The deploy's compose `-f` set, rendered into vc-compose and nowhere else.
 */
export function composeFileFlags(options = {}) {
  // Base first, then each enabled optional overlay in COMPOSE_OPTIONAL_FILES
  // order; every `.prod.yml` must follow its own base overlay.
  const files = [
    ...COMPOSE_BASE_FILES,
    ...COMPOSE_OPTIONAL_FILES.filter((e) => e.when(options)).map((e) => e.file),
  ];
  return files.flatMap((f) => ['-f', f]).join(' ');
}

/**
 * Render the Traefik dynamic-config file that instructs Traefik to obtain and
 * serve ONE cert for the deploy as the TLS default store entry.
 *
 * With `defaultGeneratedCert`, Traefik proactively requests a single cert via
 * the named resolver at startup and serves it by default for every TLS router
 * that does NOT carry an explicit `tls.certresolver` label. Every certificate
 * validates over HTTP-01, which cannot issue wildcards, so the names are
 * explicit: `main` is `traefik.${domain}` (the dashboard router, always
 * present) and `sans` lists the enabled feature hosts in the order grafana,
 * n8n, metabase.
 *
 * The apex (app + Hono API) is deliberately NOT in this cert: it gets its own
 * single-domain cert through the app router's `tls.certresolver` label.
 *
 * The file is written into `volumes/traefik/` which is already bind-mounted
 * as `/etc/traefik/dynamic:ro`. Traefik hot-reloads files from that dir.
 * Multiple files in the dir coexist fine; this file adds only a top-level
 * `tls:` key that has no overlap with the `http:` keys in middlewares.yml.
 *
 * @param {{domain: string, features?: {observability?: boolean, n8n?: boolean, metabase?: boolean}}} opts
 * @returns {string} YAML string suitable for writing to `volumes/traefik/tls-default.yml`
 */
export function renderTraefikDefaultCert({ domain, features = {} }) {
  const subs = [];
  if (features.observability) subs.push('grafana');
  if (features.n8n) subs.push('n8n');
  if (features.metabase) subs.push('metabase');
  const main = `traefik.${domain}`;
  const sans = subs.map((s) => `${s}.${domain}`);

  const lines = [
    'tls:',
    '  stores:',
    '    default:',
    '      defaultGeneratedCert:',
    '        resolver: letsencrypt',
    '        domain:',
    `          main: "${main}"`,
  ];
  if (sans.length) {
    lines.push('          sans:');
    for (const d of sans) lines.push(`            - "${d}"`);
  }

  return `# Traefik default TLS certificate — generated by Vibecarbon at deploy time.
#
# Serves as the default cert for ALL TLS routers carrying \`tls=true\` without an
# explicit certresolver (SNI fallback). Covers traefik.<domain> plus the enabled
# feature hosts, all validated over HTTP-01; the apex app gets its own cert via
# the app router's \`tls.certresolver\`.
${lines.join('\n')}
`;
}

/**
 * Render the bundle, run `fn` with its path, and remove it once `fn` settles,
 * whatever the outcome. The bundle holds the rendered .env and app.env, every
 * secret the servers get, so it never outlives the work that reads it (a
 * Ctrl-C mid-work leaves it to the exit sweep, temp-dir.js).
 *
 * @template T
 * @param {string} projectName
 * @param {object} options - renderBundle's
 * @param {(bundlePath: string) => Promise<T> | T} fn
 * @returns {Promise<T>}
 */
export async function withBundle(projectName, options, fn) {
  const renderTimer = perfTimer('deploy.bundle.pack');
  const bundlePath = renderBundle(projectName, options);
  renderTimer.end();
  try {
    return await fn(bundlePath);
  } finally {
    removeTempDir(bundlePath);
  }
}

/**
 * Render the deployment bundle to a private temp dir. The caller owns the dir
 * and must remove it (removeTempDir), as withBundle and the deploy's dispatch
 * do (tests/unit/lib/temp-dir-census.test.ts holds every caller to it). A
 * render that throws removes its own dir.
 * @param {string} projectName
 * @param {object} options
 * @returns {string} The path to the staged bundle directory
 */
export function renderBundle(projectName, options = {}) {
  // app.env is built from options.s3, else from options.appEnvReplay, else
  // from the server .env below, whose S3_ENDPOINT / S3_REGION a backupTarget
  // sets to the backups bucket's. A backupTarget with neither would hand the
  // app the backups bucket's host. The deploy always passes s3 with a target
  // and a scale replay passes no target; refuse the third shape before the
  // stage dir is made.
  if (options.backupTarget && !options.s3 && !options.appEnvReplay) {
    throw new Error(
      'renderBundle: a backupTarget needs options.s3 or options.appEnvReplay, so app.env keeps the uploads bucket instead of the backups one',
    );
  }
  const stageDir = makeTempDir('vc-deploy-bundle-');
  try {
    writeBundle(stageDir, projectName, options);
  } catch (err) {
    removeTempDir(stageDir);
    throw err;
  }
  return stageDir;
}

/**
 * Write the bundle's files into `stageDir`.
 * @param {string} stageDir
 * @param {string} projectName
 * @param {object} options - renderBundle's
 */
function writeBundle(stageDir, projectName, options) {
  const cwd = process.cwd();

  // Core Docker files
  const rootFiles = [
    'docker-compose.yml',
    'docker-compose.prod.yml',
    'Dockerfile',
    '.dockerignore',
  ];
  if (options.observability) {
    rootFiles.push('docker-compose.observability.yml', 'docker-compose.observability.prod.yml');
  }
  if (options.n8n) {
    rootFiles.push('docker-compose.n8n.yml', 'docker-compose.n8n.prod.yml');
  }
  if (options.metabase) {
    rootFiles.push('docker-compose.metabase.yml', 'docker-compose.metabase.prod.yml');
  }
  if (options.redis) rootFiles.push('docker-compose.redis.yml', 'docker-compose.redis.prod.yml');

  for (const file of rootFiles) {
    const src = join(cwd, file);
    if (existsSync(src)) {
      if (options.verbose) console.log(`[bundle] Copying ${file}`);
      cpSync(src, join(stageDir, file));
    }
  }

  // Render .env locally with overrides
  const localEnvPath = join(cwd, '.env');
  let envContent = '';
  if (existsSync(localEnvPath)) {
    envContent = readFileSync(localEnvPath, 'utf-8');
  }
  // Defense-in-depth: this baseline is echoed into the bundle line-for-line
  // below for any key without an explicit override, so an operator-secret
  // key must never survive the read — see stripOperatorSecretLines' doc for
  // why this doesn't touch envOverrides (S3 and scale-replay stay live).
  envContent = stripOperatorSecretLines(envContent);
  // Servers derive the compose project from /opt/<project>. A local
  // COMPOSE_PROJECT_NAME pin (written by `vibecarbon up` after a folder
  // rename) would move the server stack onto new, empty volumes.
  envContent = envContent
    .split('\n')
    .filter((line) => !/^\s*(export\s+)?COMPOSE_PROJECT_NAME\s*=/.test(line))
    .join('\n');

  const envOverrides = { ...(options.envOverrides || {}) };
  // The db image is the CLI's, never the project's: docker-compose.yml pulls
  // ${DB_IMAGE}:${DB_IMAGE_TAG}, and every server runs the tag of the CLI that
  // deployed it. Set after the caller's overrides so a replayed older .env
  // (scale) cannot pin a stale tag.
  // (VIBECARBON_DB_IMAGE swaps in a dev build for testing; resolveDbImage warns.)
  const dbImage = resolveDbImage();
  envOverrides.DB_IMAGE = dbImage.image;
  envOverrides.DB_IMAGE_TAG = dbImage.tag;
  // The same rule for the images the version set moves: the prod overlay reads
  // both from .env, so the value here is what the server runs.
  envOverrides.TRAEFIK_IMAGE = traefikImageRef();
  envOverrides.DOCKER_SOCKET_PROXY_IMAGE = dockerSocketProxyImageRef();
  if (options.domain) {
    envOverrides.DOMAIN = options.domain;
    envOverrides.ACME_EMAIL = `admin@${options.domain}`;
    // Single public origin: the apex serves the SPA and the Hono /api (auth
    // included, at /api/auth). SITE_URL is that one origin — auth redirects
    // and cookies, billing return URLs, and CSP/CORS all derive from it.
    envOverrides.SITE_URL = `https://${options.domain}`;
  }
  if (options.image) {
    envOverrides.APP_IMAGE = options.image;
  }
  if (options.s3) {
    envOverrides.S3_ACCESS_KEY = options.s3.accessKey;
    envOverrides.S3_SECRET_KEY = options.s3.secretKey;
    envOverrides.S3_REGION = options.s3.region;
    envOverrides.S3_ENDPOINT = options.s3.endpoint;
    envOverrides.S3_BUCKET = options.s3.bucket;
  }
  if (options.environment) {
    envOverrides.VC_ENV = options.environment;
  }
  // The backups bucket, at its own region and endpoint. On a server only the
  // db service reads `.env`'s S3_ENDPOINT / S3_REGION (wal-g's AWS_ENDPOINT /
  // AWS_REGION, docker-compose.yml), and every wal-g caller and
  // backup/tls-snapshot.sh run there; the app reads `app.env`, written below
  // from `options.s3` by buildAppRuntimeEnv. So these follow the backups
  // bucket, which an environment an older CLI put in another region keeps.
  // Set after `options.s3`, and S3_BACKUP_BUCKET in the place it always had,
  // so a same-region environment's `.env` is byte-identical to before (the
  // db container is not recreated).
  if (options.backupTarget) {
    envOverrides.S3_BACKUP_BUCKET = options.backupTarget.bucket;
    envOverrides.S3_ENDPOINT = options.backupTarget.endpoint;
    envOverrides.S3_REGION = options.backupTarget.region;
  }
  // Where backup/tls-snapshot.sh saves acme.json (tlsSnapshotS3Prefix), read
  // through the traefik service env (docker-compose.prod.yml).
  if (options.tlsSnapshotPrefix) {
    envOverrides.TLS_SNAPSHOT_S3_PREFIX = options.tlsSnapshotPrefix;
  }
  if (projectName) {
    envOverrides.PROJECT_NAME = projectName;
  }
  // Merge overrides into local copy. Deliberately NOT parseDotenv: this is
  // an in-place REWRITER, not a reader — every line envOverrides does not
  // touch (comments, blanks, key order) ships verbatim, which a
  // parse-then-serialize cannot guarantee, and no value is read out of the
  // file here. Allow-listed by exact path in
  // tests/unit/lib/dotenv-dialect-census.test.ts.
  const lines = envContent.split('\n');
  const seen = new Set();
  const merged = lines.map((line) => {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=/);
    if (m && envOverrides[m[1]] !== undefined) {
      seen.add(m[1]);
      return formatDotenvLine(m[1], envOverrides[m[1]]);
    }
    return line;
  });
  for (const [k, v] of Object.entries(envOverrides)) {
    if (!seen.has(k)) merged.push(formatDotenvLine(k, v));
  }
  const serverEnvText = merged.join('\n');
  writeFileSync(join(stageDir, '.env'), serverEnvText);

  // app.env: the only env file the app container reads on a server (the prod
  // overlay's `env_file: !override [app.env]`). Built fresh from the server
  // .env above, never copied from it: only the app's own keys, plus its
  // storage keys from the one hand-off point. A scale replay passes the old
  // server's app.env as `appEnvReplay`; a server deployed before app.env
  // existed gave its app the whole .env, so its S3_* there are what it used.
  const serverEnv = parseDotenv(serverEnvText);
  const appEnv = buildAppRuntimeEnv(
    serverEnv,
    appStorageCredential({
      s3Config: options.s3,
      previousAppEnv: options.appEnvReplay ?? serverEnv,
    }),
  );
  writeFileSync(
    join(stageDir, 'app.env'),
    `${Object.entries(appEnv)
      .map(([k, v]) => formatDotenvLine(k, v))
      .join('\n')}\n`,
  );

  const isFast = Boolean(options.image?.endsWith(':local'));
  // The one Compose command on the server (compose/command.js): the scripts
  // below and every remote command the CLI sends run it.
  writeFileSync(
    join(stageDir, VC_COMPOSE_SCRIPT),
    renderComposeCommand(composeFileFlags(options)),
    {
      mode: 0o755,
    },
  );
  writeFileSync(join(stageDir, 'reconcile.sh'), renderReconcileScript(projectName, isFast), {
    mode: 0o755,
  });
  // The add-ons started after the core stack (services/addon-start.js).
  const addons = backgroundAddons(enabledAddonNames(options));
  writeFileSync(
    join(stageDir, ADDON_SERVICES_SCRIPT),
    renderAddonServicesScript(addons.flatMap((a) => [...a.services, ...a.setup])),
    { mode: 0o755 },
  );
  writeFileSync(join(stageDir, ADDON_JOB_SCRIPT), renderAddonJobScript(projectName, addons), {
    mode: 0o755,
  });
  writeFileSync(
    join(stageDir, STANDBY_SCALE_SCRIPT),
    renderStandbyScaleScript(composeStandbyScaledServices(enabledAddonNames(options))),
    { mode: 0o755 },
  );
  writeFileSync(join(stageDir, `${projectName}.service`), renderSystemdUnit(projectName));

  const copyDirIfExist = (srcDir, destDir) => {
    const src = join(cwd, srcDir);
    if (existsSync(src)) {
      if (options.verbose) console.log(`[bundle] Copying ${srcDir} to ${destDir}`);
      cpSync(src, join(stageDir, destDir), { recursive: true });
    } else {
      if (options.verbose) console.log(`[bundle] Skipping ${srcDir} (not found)`);
    }
  };

  // No db/: the migrations ship inside the app image (the Dockerfile copies
  // db/migrations) and the app applies them at startup, so nothing on the
  // server reads them.
  copyDirIfExist('volumes/db', 'volumes/db');

  // volumes/traefik/ — dynamic-config directory mounted into Traefik.
  // Always ensure the dir exists in the bundle so Traefik's file provider
  // has a valid mount target even if the source dir is absent.
  mkdirSync(join(stageDir, 'volumes', 'traefik'), { recursive: true });

  const traefikMiddlewares = join(cwd, 'volumes', 'traefik', 'middlewares.yml');
  if (existsSync(traefikMiddlewares)) {
    cpSync(traefikMiddlewares, join(stageDir, 'volumes', 'traefik', 'middlewares.yml'));
  }

  // Render tls-default.yml only when a domain is known (production deploys).
  // This instructs Traefik to proactively obtain ONE cert for the deploy and
  // serve it as the default for all TLS routers via SNI, with explicit names.
  // The file coexists with middlewares.yml — both live under the same `tls:`
  // / `http:` top-level keys respectively; Traefik merges all files in the dir.
  if (options.domain) {
    const tlsDefaultYaml = renderTraefikDefaultCert({
      domain: options.domain,
      features: {
        observability: options.observability,
        n8n: options.n8n,
        metabase: options.metabase,
      },
    });
    writeFileSync(join(stageDir, 'volumes', 'traefik', 'tls-default.yml'), tlsDefaultYaml);
    if (options.verbose) console.log('[bundle] Rendered volumes/traefik/tls-default.yml');
  }

  copyDirIfExist('backup', 'backup');
  if (options.n8n) copyDirIfExist('volumes/n8n', 'volumes/n8n');
  if (options.metabase) copyDirIfExist('volumes/metabase', 'volumes/metabase');

  if (options.observability) {
    copyDirIfExist('prometheus', 'prometheus');
    copyDirIfExist('grafana', 'grafana');
    for (const subdir of ['prometheus', 'grafana', 'loki', 'alloy']) {
      copyDirIfExist(`volumes/${subdir}`, `volumes/${subdir}`);
    }
  }
}
